# R=5 exhaustive with grouping of equal cache cost in intermediate combinations
import random, subprocess, bisect, time
from functools import lru_cache
WIDTH=[16,8,4]; LANES=[4,8,16]
def pages_for(s,b,m):
 K=s if b==0 else b-1
 return (32+4*b+K*WIDTH[m]+63)//64
def comps(s):
 for b in range(2,min(9,s)+1):
  def rec(rem,k,p):
   if k==1: yield p+[rem]
   else:
    for x in range(1,rem-k+2): yield from rec(rem-x,k-1,p+[x])
  yield from rec(s,b,[])
def stats(st,bursts):
 R=len(st);Q=[[0]*(R+1) for _ in range(R+1)];T=[[0]*(R+1) for _ in range(R+1)];qr=[0]*R
 for rep,aa in bursts:
  tu=[0]*R
  for a in aa: r=bisect.bisect_right(st,a)-1;qr[r]+=rep;tu[r]=1
  pr=[0]
  for x in tu:pr.append(pr[-1]+x)
  for i in range(R):
   for j in range(i+1,R+1):
    if pr[j]-pr[i]:T[i][j]+=rep
 pr=[0]
 for x in qr:pr.append(pr[-1]+x)
 for i in range(R):
  for j in range(i+1,R+1):Q[i][j]=pr[j]-pr[i]
 return Q,T
def brute(st,Q,T,cost,C):
 R=len(st)
 @lru_cache(None)
 def sub(i,j):
  s=j-i;qv=Q[i][j];tv=T[i][j];sp=st[j-1]-st[i];legal=[0]
  if sp<1<<64:legal.append(1)
  if sp<1<<32:legal.append(2)
  out={}
  def add(w,p,c):
   old=out.get(c)
   if old is None or (w,p)<old:out[c]=(w,p)
  if s<=8:
   for m in legal:
    P=pages_for(s,0,m);kw=(s+LANES[m]-1)//LANES[m]+cost[2][m];base=kw*qv
    add(base+P*cost[1]*tv,P,0)
    if P<=C:add(base+P*cost[0]*tv,P,P)
  for comp in comps(s):
   b=len(comp); combos={0:(0,0)};pos=i
   for x in comp:
    vv=sub(pos,pos+x);ng={}
    for c1,(w1,p1) in combos.items():
     for c2,(w2,p2) in vv.items():
      c=c1+c2
      if c>C:continue
      cand=(w1+w2,p1+p2)
      if c not in ng or cand<ng[c]:ng[c]=cand
    combos=ng;pos+=x
   for cs,(ws,ps) in combos.items():
    for m in legal:
     P=pages_for(s,b,m);kw=(b-1+LANES[m]-1)//LANES[m]+cost[2][m];base=ws+kw*qv
     add(base+P*cost[1]*tv,ps+P,cs)
     if cs+P<=C:add(base+P*cost[0]*tv,ps+P,cs+P)
  return tuple(out.items())
 by={c:(w,p) for c,(w,p) in sub(0,R)}
 return by
def run_plan(st,hops,bursts,cost,C):
 lines=['PLAN 1',f"{C} {cost[0]} {cost[1]} {cost[2][0]} {cost[2][1]} {cost[2][2]} 1 {len(bursts)}",str(len(st))]
 lines += [f'{x:032x} {-1 if h is None else h}' for x,h in zip(st,hops)]
 for v,rep,aa in bursts:
  row=f'{v} {rep} {len(aa)}';
  if aa:row+=' '+' '.join(f'{a:032x}' for a in aa)
  lines.append(row)
 p=subprocess.run(['tmp/engine_test'],input=('\n'.join(lines)+'\n').encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 if p.returncode:raise RuntimeError(p.stderr.decode())
 out=p.stdout.decode().splitlines();at=1
 for v,r,aa in bursts: A=int(out[at]);at+=1+A
 return tuple(map(int,out[at].split()))
random.seed(123)
t0=time.time()
for trial in range(150):
 R=5;C=random.randint(0,4)
 st=[0]
 for _ in range(R-1):st.append(st[-1]+random.randint(1,random.choice([5,100,1<<35,1<<65])))
 hops=[None if random.random()<.1 else random.randint(0,9) for _ in range(R)]
 bursts=[]
 for _ in range(random.randint(0,3)):
  rep=random.randint(1,4);aa=[]
  for __ in range(random.randint(0,6)):
   r=random.randrange(R);end=st[r+1] if r+1<R else st[r]+100
   aa.append(random.randrange(st[r],min(end,st[r]+100)))
  bursts.append((0,rep,aa))
 Q,T=stats(st,[(r,a) for v,r,a in bursts]);cost=[random.randint(1,3),random.randint(3,8),[random.randint(0,2) for _ in range(3)]]
 by=brute(st,Q,T,cost,C);bw,bp=min(by.values());fixed=1+(4*R+63)//64
 got=run_plan(st,hops,bursts,cost,C);exp=(bw,bp+fixed)
 if got!=exp:
  print('FAIL',trial,got,exp,cost,list(map(hex,st)),hops,bursts,by);raise SystemExit(1)
print('R5 PASS',time.time()-t0)
